package ivorius.psychedelicraft.client.render;

import net.minecraft.client.model.ModelBase;
import net.minecraft.client.model.ModelRenderer;

final class RastaHeadModel extends ModelBase {
    private final ModelRenderer head;
    private final ModelRenderer hat;
    private final ModelRenderer joint;

    RastaHeadModel() {
        textureWidth = 128;
        textureHeight = 64;

        head = box(0, 0, -4, -8, -4, 8, 8, 8);
        ModelRenderer nose = box(33, 0, -0.5F, -4.8F, -5, 1, 2, 1);
        nose.rotateAngleX = -0.0743572F;
        head.addChild(nose);
        head.addChild(box(38, 0, -1, -4.2F, -4.5F, 2, 1, 1));
        head.addChild(box(0, 17, -4.5F, -7.5F, -4.5F, 9, 11, 9));
        hat = box(0, 38, -5, -10, -8.5F, 10, 7, 12);
        hat.rotateAngleX = -0.669215F;
        joint = box(0, 0, -0.5F, -3.5F, -5, 1, 1, 2);
        joint.rotateAngleX = 0.4089647F;
        joint.rotateAngleY = -0.2602503F;
    }

    private ModelRenderer box(int u, int v, float x, float y, float z, int width, int height, int depth) {
        ModelRenderer part = new ModelRenderer(this, u, v);
        part.mirror = true;
        part.addBox(x, y, z, width, height, depth);
        return part;
    }

    void render() {
        DrugRenderer.drawWorldPart(head, 0.0625F);
        DrugRenderer.drawWorldPart(hat, 0.0625F);
        DrugRenderer.drawWorldPart(joint, 0.0625F);
    }
}
